#include <iostream>
#include <string>
#include <vector>
using namespace std;

// 求next数组
void getNext(string T, vector<int>& next) {
    int m = T.length();
    next.resize(m);
    next[0] = -1;
    int j = 0, k = -1;
    while (j < m - 1) {
        if (k == -1 || T[j] == T[k]) {
            j++; k++;
            next[j] = k;
        } else {
            k = next[k];
        }
    }
}

// 求改进的nextval数组
void getNextval(string T, vector<int>& nextval) {
    int m = T.length();
    nextval.resize(m);
    nextval[0] = -1;
    int j = 0, k = -1;
    while (j < m - 1) {
        if (k == -1 || T[j] == T[k]) {
            j++; k++;
            if (T[j] != T[k]) nextval[j] = k;
            else nextval[j] = nextval[k];  // 字符相同，跳过
        } else {
            k = nextval[k];
        }
    }
}

// KMP匹配
int IndexKMP(string S, string T, int pos = 0) {
    int n = S.length(), m = T.length();
    if (m == 0) return pos;
    vector<int> next;
    getNext(T, next);
    int i = pos, j = 0;
    while (i < n && j < m) {
        if (j == -1 || S[i] == T[j]) { i++; j++; }
        else j = next[j];
    }
    return (j >= m) ? i - m : -1;
}

// 用nextval的KMP
int IndexKMP2(string S, string T, int pos = 0) {
    int n = S.length(), m = T.length();
    if (m == 0) return pos;
    vector<int> nextval;
    getNextval(T, nextval);
    int i = pos, j = 0;
    while (i < n && j < m) {
        if (j == -1 || S[i] == T[j]) { i++; j++; }
        else j = nextval[j];
    }
    return (j >= m) ? i - m : -1;
}

// 示例：
// S = "ababcabcacbab", T = "abcac"
// next[] = [-1, 0, 0, 0, 1]
// nextval[] = [-1, 0, 0, -1, 1]
// 匹配位置：索引5（即第6个字符处）

// 经典测试：S="aaaaaab", T="aaab"
// 朴素算法：每次需比较到最后一位才失配，O(n*m)
// KMP算法：next=[-1,0,1,2], O(n+m)

#include <iostream>
using namespace std;

#define MAXSIZE 1000

typedef struct {
    int i, j;   // 行列下标（从1开始）
    int e;      // 元素值
} Triple;

typedef struct {
    Triple data[MAXSIZE];
    int mu, nu, tu;  // 行数、列数、非零元个数
} TSMatrix;

// 稀疏矩阵快速转置 O(nu + tu)
void FastTranspose(TSMatrix M, TSMatrix &T) {
    T.mu = M.nu; T.nu = M.mu; T.tu = M.tu;
    if (T.tu == 0) return;

    int num[100] = {0};  // 每列非零元个数
    int cpot[100] = {0}; // 每列第一个非零元在T中的位置

    // 步骤1：统计每列非零元个数
    for (int t = 1; t <= M.tu; t++) num[M.data[t].j]++;

    // 步骤2：计算每列第一个非零元位置
    cpot[1] = 1;
    for (int col = 2; col <= M.nu; col++)
        cpot[col] = cpot[col-1] + num[col-1];

    // 步骤3：遍历原矩阵，按cpot指示位置放入转置矩阵
    for (int p = 1; p <= M.tu; p++) {
        int col = M.data[p].j;
        int q = cpot[col];
        T.data[q].i = M.data[p].j;
        T.data[q].j = M.data[p].i;
        T.data[q].e = M.data[p].e;
        cpot[col]++;
    }
}

// 输出矩阵
void PrintMatrix(TSMatrix M) {
    cout << "Matrix (" << M.mu << "x" << M.nu << "), " << M.tu << " non-zero:" << endl;
    int k = 1;
    for (int i = 1; i <= M.mu; i++) {
        for (int j = 1; j <= M.nu; j++) {
            if (k <= M.tu && M.data[k].i == i && M.data[k].j == j) {
                cout << M.data[k].e << " "; k++;
            } else cout << "0 ";
        }
        cout << endl;
    }
}

// 示例矩阵（3行4列）：
// 0 12  9  0
// 0  0  0  0
// -3 0  0 14
// 三元组：(1,2,12), (1,3,9), (3,1,-3), (3,4,14)
